@pytest.mark.parametrize("command", ["sync", "status"])
def test_other_commands_are_not_implemented_yet(server, conn, local, command, capsys):
    write(local, {"a": b"a"})
    put(conn, "b", b"b")

    assert main([command, str(local), "--server", url_of(server)], environ={}) == 1

    assert f"'{command}' is not implemented yet" in capsys.readouterr().err
    assert remote_state(conn) == {"b": sha(b"b")}
    assert sorted(p.name for p in local.iterdir()) == ["a"]

    assert proc.stdout == "0 downloaded, 1 already up to date\n"


@pytest.mark.parametrize("command", ["push", "pull"])
def test_unreachable_server(tmp_path, command):
    proc = run(command, str(tmp_path), "--server", "http://127.0.0.1:1")
    assert proc.returncode == 1
    assert proc.stderr == "syncbox: error: cannot reach server http://127.0.0.1:1: Connection refused\n"


